import java.net.*;import java.nio.file.*;import java.util.*;
/** HF44 fixed difficulty, fixed roster and shared damage/healing checks. */
public class HF44DungeonBalanceCheck {
 static int checks;
 static void ok(boolean v,String s){if(!v)throw new AssertionError(s);checks++;}
 static Battle make(int stage,int difficulty,int party){Battle b=new Battle(new Arsenal717ServerCheck.Ground());b.start(true);b.configureOnlineTeam();b.dungeonStage=stage;b.dungeonDifficulty=difficulty;b.dungeonParty=party;b.active=0;b.explicitHumans=true;
  for(int i=0;i<b.units.length;i++){b.units[i].hp=0;b.units[i].npc=0;}for(int i=0;i<party;i++){Battle.Unit u=b.units[2*i];u.human=true;u.weapon=3;u.experience=Progression.experienceForLevel(stage<3?15:30);ItemRules.apply(u,3);u.team=0;}
  if(stage>=3)TribalRules.setup(b,stage-2,difficulty,false);else{b.unitCount=stage==1?13:12;AntCaveRules.spawn(b,1,stage==1?1:3,difficulty);}
  return b;
 }
 static void stats(int stage,int npc){int prevHp=0,prevAtk=-1,prevDef=-1,prevLuck=-1;for(int d=0;d<4;d++){int hp=DungeonBalance.hp(stage,npc,d,1),atk=DungeonBalance.attack(stage,npc,d),def=DungeonBalance.defense(stage,npc,d),luck=DungeonBalance.luck(stage,npc,d);ok(hp>prevHp&&atk>=prevAtk&&def>=prevDef&&luck>=prevLuck,"monotone difficulty");prevHp=hp;prevAtk=atk;prevDef=def;prevLuck=luck;int last=0;for(int n=1;n<=3;n++){int h=DungeonBalance.hp(stage,npc,d,n);ok(h>0&&h<=65000&&h>=last,"HP within wire range");if(DungeonBalance.boss(npc)&&n>1)ok(h>last,"boss scales by roster");else if(!DungeonBalance.boss(npc))ok(h==hp,"ordinary mob independent of roster");last=h;}
  ok(CombatBalance.critChance(luck)<=4000&&CombatBalance.penetration(luck)<=20,"luck caps");}}
 static void hit(Battle b,int attacker,int target,int raw){var a=b.units[attacker];var v=b.units[target];int x=v.x*256,y=Battle.targetY(v)*256;int before=v.hp;int hit=CombatBalance.damage(b,attacker,target,raw,x,y,0);boolean special=CombatBalance.special(b,attacker,target,raw,x,y,0);Battle.Ball p=new Battle.Ball();p.owner=attacker;p.x=x;p.y=y;p.radius=1;p.damage=raw;p.sulanVictim=target;b.impact(p);ok(v.hp==Math.max(0,before-hit),"actual NPC hit equals combat formula");ok(b.damagePopups[b.damagePopupCount-1].powered==special,"special popup agrees");}
 static void heal(){for(int hp:new int[]{6750,9000,15000,19000,19003}){Battle b=make(0,0,1);b.dungeonStage=0;b.botPhase=0;b.active=0;b.units[0].maxHp=hp;b.units[0].hp=1;b.units[0].heals=5;for(int j=0;j<5;j++){b.units[0].energy=240;ok(b.prop(3),"heal available");ok(b.units[0].hp==1+(j+1)*(hp/10),"heal 10 percent");}b.units[0].energy=240;ok(!b.prop(3)&&b.units[0].hp-1<=hp/2,"five uses max 50 percent");}
  Battle b=make(0,0,2);b.dungeonStage=0;b.active=0;b.units[0].kit[0]=2;b.units[0].hp=b.units[2].hp=1;b.units[0].energy=240;ok(b.item(0),"group heal");for(int i:new int[]{0,2})ok(b.units[i].hp==1+b.units[i].maxHp/10,"group heal based on each recipient HP");ok(!b.item(0),"group item no reuse");}
 static void roomCheck()throws Exception{try(var s=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),new CloudStore.Memory())){s.clock.shutdownNow();for(int stage:new int[]{1,2,3,4,6})for(int d=0;d<4;d++)for(int n=1;n<=3;n++){var host=HF38SulanRecoveryCheck.player("test-"+stage+"-"+d+"-"+n);host.profile.experience=Progression.experienceForLevel(stage<3?15:30);host.profile.dungeonClear=true;var r=s.new Room(host,6,2,-1,true);r.kind=3;r.strict=true;r.dungeonStage=stage;r.difficulty=d;for(int i=1;i<n;i++){r.selectedBots[2*i]=7;}r.refreshWaiting();r.start();Battle b=r.battle;ok(b.dungeonParty==n,"party includes occupied AI, not empty seats");for(int i=0;i<b.unitCount;i++){var u=b.units[i];if(u.npc>0&&u.hp>0){ok(u.statsEnabled&&u.maxHp==DungeonBalance.hp(stage,u.npc,d,n),"actual NPC spawn HP");ok(DungeonBalance.attackOf(b,i)==DungeonBalance.attack(stage,u.npc,d),"actual NPC attack");ok(u.defense==DungeonBalance.defense(stage,u.npc,d)&&u.luck==DungeonBalance.luck(stage,u.npc,d),"actual NPC defense and luck");}else if(i>0&&i<6&&i%2==0&&u.hp>0){ok(!u.human&&u.statsEnabled&&u.forgeWeaponBonus>0,"AI uses upgraded character stats");}}
   if(n>1){b.units[2].hp=0;if(stage<3)Dungeon780.progress(r);ok(b.dungeonParty==n,"party scale fixed after death");}
  }}}
 public static void main(String[] args)throws Exception{for(int npc=1;npc<=15;npc++){int stage=npc<=2?1:npc==3?2:npc<=6?3:npc<=13?4:6;stats(stage,npc);}
  for(int d=0;d<4;d++)for(int n=1;n<=3;n++){Battle b=make(6,d,n);b.units[0].hp=b.units[0].maxHp=30000;b.units[0].x=50;b.units[1].x=350;b.units[0].luck=1000;hit(b,0,1,1600);b.units[0].defense=600;hit(b,1,0,1800);int raw=1000;int before=b.units[0].hp;int expected=CombatBalance.damage(b,1,0,raw,b.units[0].x*256,b.units[0].y*256,b.tribalClock);SulanRules.hurt(b,0,raw);ok(before-b.units[0].hp==expected,"direct skill uses shared formula");int fixed=b.dungeonParty;b.units[2].hp=0;TribalRules.spawn(b,1,TribalRules.RAGE,300);ok(b.units[1].maxHp==DungeonBalance.hp(6,TribalRules.RAGE,d,fixed),"transformation keeps initial roster");}
  heal();roomCheck();ok(DungeonBalance.rewardTier(3)==2,"superhard same hard rewards");System.out.println("PASS "+checks+" HF44 dungeon balance, fixed party, bots, damage, healing checks");}
}
